{
  "scenario_title": "Daily energy delivery and peak load across residential distribution feeders in Grid City, Q1 2024",
  "data_context": "The municipal electric utility SCADA system logged daily aggregate electricity delivery, peak power demand, and power factor across residential distribution feeders from January through March 2024 to monitor winter heating demand and plan feeder reinforcement.",
  "script": "dim(\"substation\", [\"Maple Substation\", \"Pine Substation\"], weights=[0.55, 0.45], group=\"grid\")\ndim(\"feeder_id\", [\"Feeder-101\", \"Feeder-102\", \"Feeder-201\", \"Feeder-202\"], parent=\"substation\", weights={\"Maple Substation\": [0.55, 0.45, 0.0, 0.0], \"Pine Substation\": [0.0, 0.0, 0.52, 0.48]}, group=\"grid\")\ndim(\"customer_class\", [\"Single Family\", \"Multi-Family\", \"Mixed Residential\"], weights=[0.50, 0.30, 0.20], group=\"customer\")\n\ntime(\"reading_date\", start=\"2024-01-01\", end=\"2024-03-31\", freq=\"daily\")\n\nmeasure(\"energy_delivered_mwh\", \"clip(28 + {\\\"Single Family\\\": 7, \\\"Multi-Family\\\": -6, \\\"Mixed Residential\\\": 0}[customer_class] + {\\\"Feeder-101\\\": 3.5, \\\"Feeder-102\\\": -1.5, \\\"Feeder-201\\\": 2.0, \\\"Feeder-202\\\": -4.0}[feeder_id] + 5.0 * cos(reading_date / 91 * 3.14159) + gaussian(0, 2.2), 8, 55)\", unit=\"MWh\", additive=True)\nmeasure(\"peak_demand_mw\", \"clip(energy_delivered_mwh / 14.0 + gaussian(0, 0.2), 0.5, 6.0)\", unit=\"MW\", additive=False)\nmeasure(\"power_factor\", \"clip(0.95 - 0.03 * [customer_class=Mixed Residential] + gaussian(0, 0.015), 0.80, 0.99)\", unit=\"ratio\", additive=False)\n\nemit(360)",
  "intents": [
    {
      "sentence": "Compare average daily energy delivered across the distribution feeders",
      "columns": [
        "feeder_id",
        "energy_delivered_mwh"
      ],
      "aggregate": "AVG",
      "family": "comparison"
    },
    {
      "sentence": "Track the decline in total energy delivered over the quarter as winter cold abates",
      "columns": [
        "reading_date",
        "energy_delivered_mwh"
      ],
      "aggregate": "SUM",
      "family": "trend"
    },
    {
      "sentence": "Analyze how daily peak demand scales with total energy delivered",
      "columns": [
        "energy_delivered_mwh",
        "peak_demand_mw"
      ],
      "aggregate": "NONE",
      "family": "relation"
    }
  ]
}
